import { state, saveState } from '../core/state.js';
import { escapeHtml, escapeAttr, domIdToken } from '../core/dom.js';
import { touchCase } from '../core/cases.js';
import { showSaved } from '../ui.js';
import { toNum } from '../calculations/stair-eligibility.js';

/* Wheelchair form and derived dimensions
+ * Mechanically extracted from index_2.html. Keep public function names stable while modularizing.
 */
/* ==========================================================================
   Wheelchair Form Rendering
   ========================================================================== */
function wcR(fieldName, value, label, wc) {
  const checked = wc[fieldName] === value ? 'checked' : '';
  const id = `wc_${fieldName}_${domIdToken(value)}`;
  return `<label class="wc-option" for="${id}">
    <input type="radio" id="${id}" name="wc_${fieldName}" data-wc-radio="${fieldName}" value="${escapeAttr(value)}" ${checked}>
    <span class="wc-option-text">${escapeHtml(label)}</span>
  </label>`;
}
function wcRI(fieldName, value, label, wc) {
  const checked = wc[fieldName] === value ? 'checked' : '';
  const id = `wc_${fieldName}_${domIdToken(value)}`;
  return `<label class="wc-inline-option" for="${id}">
    <input type="radio" id="${id}" name="wc_${fieldName}" data-wc-radio="${fieldName}" value="${escapeAttr(value)}" ${checked}>
    <span class="wc-inline-option-text">${escapeHtml(label)}</span>
  </label>`;
}
function wcC(fieldName, value, label, wc) {
  const checked = Array.isArray(wc[fieldName]) && wc[fieldName].includes(value) ? 'checked' : '';
  const id = `wc_${fieldName}_${domIdToken(value)}`;
  return `<label class="wc-inline-option" for="${id}">
    <input type="checkbox" id="${id}" data-wc-checkbox="${fieldName}" value="${escapeAttr(value)}" ${checked}>
    <span class="wc-inline-option-text">${escapeHtml(label)}</span>
  </label>`;
}
function wcCDisabled(fieldName, value, label, wc, disabled) {
  const checked = Array.isArray(wc[fieldName]) && wc[fieldName].includes(value) ? 'checked' : '';
  const id = `wc_${fieldName}_${domIdToken(value)}`;
  return `<label class="wc-inline-option" for="${id}">
    <input type="checkbox" id="${id}" data-wc-checkbox="${fieldName}" value="${escapeAttr(value)}" ${checked} ${disabled ? 'disabled' : ''}>
    <span class="wc-inline-option-text">${escapeHtml(label)}</span>
  </label>`;
}
function wcNum(fieldName, label, unit, wc) {
  return `<div class="wc-field">
    <label class="wc-label">${label}</label>
    <div class="wc-num-wrap">
      <input type="number" inputmode="decimal" step="0.1" min="0" class="wc-num-input"
             data-wc-field="${fieldName}" value="${escapeAttr(wc[fieldName])}" placeholder="—">
      <span class="unit">${unit}</span>
    </div>
  </div>`;
}

