  const pressureCurrentVisible = wc.pressureInjury === '目前有' ? 'visible' : '';

  const shoeNo = !wc.kneeToFootWithShoe ? 'checked' : '';
  const shoeYes = wc.kneeToFootWithShoe ? 'checked' : '';

