function saveWcField(field, value) {
  const c = state.cases[state.currentCaseId];
  if (!c) return;
  c.wheelchair[field] = value;
  touchCase(c.id);
  saveState();
  updateWheelchairDimensions();
}

function updateWcConditional(field, value) {
  if (field === 'otherContracture') {
    const el = document.getElementById('wc-sub-otherContracture');
    if (el) el.classList.toggle('visible', value === '有');
  } else if (field === 'abnormalTone') {
    const el = document.getElementById('wc-sub-abnormalTone');
    if (el) el.classList.toggle('visible', value !== '' && value !== '無');
  } else if (field === 'pressureInjury') {
    const pastEl = document.getElementById('wc-sub-pressureInjury-past');
    const curEl = document.getElementById('wc-sub-pressureInjury-current');
    if (pastEl) pastEl.classList.toggle('visible', value === '過去有' || value === '目前有');
    if (curEl) curEl.classList.toggle('visible', value === '目前有');
  } else if (field === 'tubes') {
    const showOther = Array.isArray(value) ? value.includes('其他') : false;
    const el = document.getElementById('wc-sub-tubes-other');
    if (el) el.classList.toggle('visible', showOther);
  } else if (field === 'hipNoLimitL') {
    const el = document.getElementById('wc-sub-hipL');
    if (el) el.style.display = value ? 'none' : '';
  } else if (field === 'hipNoLimitR') {
    const el = document.getElementById('wc-sub-hipR');
    if (el) el.style.display = value ? 'none' : '';
  } else if (field === 'kneeNoLimitL') {
    const el = document.getElementById('wc-sub-kneeL');
    if (el) el.style.display = value ? 'none' : '';
  } else if (field === 'kneeNoLimitR') {
    const el = document.getElementById('wc-sub-kneeR');
    if (el) el.style.display = value ? 'none' : '';
  }
}

/* ==========================================================================
   Wheelchair Dimensions
   ========================================================================== */
function computeWheelchairDimensions(wc) {
  const sw = toNum(wc.seatWidth);
  const hk = toNum(wc.hipToKnee);
  const kf = toNum(wc.kneeToFoot);
  const sh = toNum(wc.shoulderHeight);
  const ua = toNum(wc.upperArmVertical);
  return {
    seatW: sw !== null ? sw + 5 : null,
    seatD: hk !== null ? hk - 3 : null,
    leg: kf !== null ? (wc.kneeToFootWithShoe ? kf : kf + 3) : null,
    arm: (sh !== null && ua !== null) ? sh - ua + 3 : null
  };
}

function updateWheelchairDimensions() {
  const c = state.cases[state.currentCaseId];
  if (!c) return;
  if (!document.getElementById('wcDimensions')) return;
  const d = computeWheelchairDimensions(c.wheelchair);
  const set = (id, v, u) => {
    const el2 = document.getElementById(id);
    if (!el2) return;
    if (v !== null) {
      el2.className = 'wc-dim-value';
      el2.textContent = (Math.round(v * 10) / 10) + ' ' + u;
    } else {
      el2.className = 'wc-dim-value empty';
      el2.textContent = '—';
    }
  };
  set('wcDim-seatW', d.seatW, 'cm');
  set('wcDim-seatD', d.seatD, 'cm');
  set('wcDim-leg', d.leg, 'cm');
  set('wcDim-arm', d.arm, 'cm');
}

export {
  wcR, wcRI, wcC, wcCDisabled, wcNum, renderWheelchairForm,
  saveWcField, updateWcConditional, computeWheelchairDimensions,
  updateWheelchairDimensions
};
